// Test the threshold parsing logic

function parseThresholds(thresholdStrings, availableMetricIds) {
  if (!thresholdStrings || thresholdStrings.length === 0) {
    return null;
  }

  const thresholds = {};
  const validMetricIds = availableMetricIds || ['exact_match', 'toxicity', 'length_variance'];

  for (const thresholdStr of thresholdStrings) {
    const match = thresholdStr.match(/^([a-z_]+)=([0-9.]+)$/i);
    if (!match) {
      throw new Error(`Malformed threshold: '${thresholdStr}'. Expected format: <metric>=<number>`);
    }

    const [, metricId, valueStr] = match;
    const value = Number.parseFloat(valueStr);

    if (Number.isNaN(value) || value < 0 || value > 1) {
      throw new Error(`Invalid threshold value for '${metricId}': ${valueStr}. Must be a number between 0 and 1.`);
    }

    if (!validMetricIds.includes(metricId)) {
      throw new Error(`Unknown metric ID: '${metricId}'. Valid metric IDs: ${validMetricIds.join(', ')}`);
    }

    thresholds[metricId] = value;
  }

  return thresholds;
}

// Test cases
console.log('Test 1: No thresholds');
console.log(parseThresholds(null) === null ? 'PASS' : 'FAIL');

console.log('\nTest 2: Valid single threshold');
const result2 = parseThresholds(['exact_match=0.9']);
console.log(result2?.exact_match === 0.9 ? 'PASS' : 'FAIL');

console.log('\nTest 3: Valid multiple thresholds');
const result3 = parseThresholds(['exact_match=0.9', 'toxicity=0.95']);
console.log(result3?.exact_match === 0.9 && result3?.toxicity === 0.95 ? 'PASS' : 'FAIL');

console.log('\nTest 4: Malformed threshold (missing equals)');
try {
  parseThresholds(['exact_match0.9']);
  console.log('FAIL - should have thrown');
} catch (e) {
  console.log('PASS - threw error as expected');
}

console.log('\nTest 5: Invalid threshold value (> 1)');
try {
  parseThresholds(['exact_match=1.5']);
  console.log('FAIL - should have thrown');
} catch (e) {
  console.log('PASS - threw error as expected');
}

console.log('\nTest 6: Unknown metric');
try {
  parseThresholds(['unknown_metric=0.9']);
  console.log('FAIL - should have thrown');
} catch (e) {
  console.log('PASS - threw error as expected');
}

EOF
